steps.code:
# Let's fetch pending requests with proper pagination.
pending_requests = []
for page in range(0, 10):
    resp = apis.venmo.show_received_payment_requests(access_token=venmo_login['access_token'], status='pending', page_index=page, page_limit=20)
    if not resp:
        break
    pending_requests.extend(resp)
    if len(resp) < 20:
        break
print(pending_requests)

